//! Terminal frontend: renders `core::View`, maps keys to `core::Action`.

use crossterm::event::{self, Event as CtEvent, KeyCode, KeyEventKind};
use ratatui::Frame;
use ratatui::layout::Constraint;
use ratatui::layout::Layout;
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{List, ListItem, Paragraph};
use smash_backend::Files;
use smash_client::Client;
use smash_core::{Action, Tone, View};

fn draw(frame: &mut Frame, view: &View) {
    let [header, body, footer] = Layout::vertical([
        Constraint::Length(1),
        ratatui::layout::Constraint::Min(0),
        ratatui::layout::Constraint::Length(1),
    ])
    .areas(frame.area());

    frame.render_widget(
        Paragraph::new(Line::from(Span::styled(
            view.title.clone(),
            Style::new().add_modifier(Modifier::BOLD),
        ))),
        header,
    );

    let rows: Vec<ListItem> = view
        .rows
        .iter()
        .map(|row| {
            let mut style = match row.tone {
                Tone::Accent => Style::new().fg(Color::Cyan),
                Tone::Muted => Style::new().fg(Color::DarkGray),
                Tone::Error => Style::new().fg(Color::Red),
                Tone::Normal => Style::new(),
            };
            if row.selected {
                style = style.bg(Color::Blue).fg(Color::Black);
            }
            ListItem::new(format!(
                "{}{}",
                if row.selected { "> " } else { "  " },
                row.text
            ))
            .style(style)
        })
        .collect();
    frame.render_widget(List::new(rows), body);

    let status = view.prompt.clone().unwrap_or_else(|| view.status.clone());
    frame.render_widget(
        Paragraph::new(status).style(Style::new().fg(Color::DarkGray)),
        footer,
    );
}

fn main() -> std::io::Result<()> {
    let dir = Files::default_dir();
    let ext = smash_ext::Ext::load_dir(dir.join("extensions"));
