        Ok(session) => Box::new((session, ext)),
        Err(_) => Box::new(ext),
    };
    let mut client = Client::with_hooks(Files::new(dir), hooks);
    client.start();

    let mut terminal = ratatui::init();
    let result = run(&mut terminal, &mut client);
    ratatui::restore();
    result
}

